            raise ValueError('missing or empty 001')
        if rec_id in seen_ids:
            raise ValueError('duplicate record id')
        seen_ids.add(rec_id)
        records.append({'id': rec_id, 'controls': controls, 'fields': fields})

    records.sort(key=lambda r: r['id'])
