sys.path.insert(0, str(ROOT / 'domains' / 'languages'))
from model import load_payload
from transform import transform

class TestLanguages(unittest.TestCase):
    def test_transform_shape_and_rule(self):
        contract = {"name": "languages", "operation": "marc_languages",
                    "inputs": ["inputs/case.json", "outputs/reader.json"],
                    "output": "outputs/languages.json"}
        raw = {"language_codes": ["eng", "ger", "lat", "fra"]}
        reader = {"records": [
            {"id": "r1", "controls": {"008": " "*35 + "eng" + " "*3},
             "fields": [{"tag": "041", "subfields": [{"code": "a", "value": "gerlat"}]}]},
            {"id": "r2", "controls": {"008": " "*35 + "fra" + " "*3},
             "fields": [{"tag": "041", "subfields": [{"code": "a", "value": "ger"}]}]},
        ]}
        result = transform([raw, reader], contract)
        self.assertEqual(set(result), {"name", "result"})
        self.assertEqual(result["name"], "languages")
        recs = result["result"]["records"]
        self.assertEqual(recs[0]["languages"], ["eng", "ger", "lat"])
        self.assertEqual(recs[1]["languages"], ["fra", "ger"])

    def test_008_too_short(self):
        contract = {"name": "languages", "inputs": ["a", "b"], "output": "o"}
        raw = {"language_codes": ["eng"]}
        reader = {"records": [{"id": "r", "controls": {"008": "short"},
                               "fields": []}]}
        with self.assertRaises(ValueError):
            transform([raw, reader], contract)

    def test_041_bad_length(self):
        contract = {"name": "languages", "inputs": ["a", "b"], "output": "o"}
        raw = {"language_codes": ["eng"]}
        reader = {"records": [{"id": "r", "controls": {},
                               "fields": [{"tag": "041", "subfields": [{"code": "a", "value": "engx"}]}]}]}
        with self.assertRaises(ValueError):
            transform([raw, reader], contract)

    def test_load_payload_rejects_nan(self):
        import tempfile
        with tempfile.NamedTemporaryFile('w', suffix='.json', delete=False) as f:
            f.write('{"a": NaN}')
            p = f.name
        with self.assertRaises(ValueError):
            load_payload(p)

if __name__ == '__main__':
    unittest.main()
