import re
import xml.etree.ElementTree as ET


def _unwrap(payload):
    if isinstance(payload, dict) and set(payload) == {'name', 'result'}:
        return payload['result']
    return payload


def _local(tag):
    if tag.startswith('{'):
        return tag.split('}', 1)[1]
    return tag


def _clean_text(text):
    return text if text is not None else ''


def transform(payloads, contract):
    if len(payloads) != len(contract['inputs']):
        raise ValueError('payload count mismatch')
    raw = _unwrap(payloads[0])
    if not isinstance(raw, dict):
        raise ValueError('input must be object')
    xml_text = raw.get('xml')
    language_codes = raw.get('language_codes')
    if not isinstance(xml_text, str):
        raise ValueError('xml must be string')
    if not isinstance(language_codes, list):
        raise ValueError('language_codes must be list')
    for code in language_codes:
        if not isinstance(code, str) or len(code) != 3 or not code.islower() or not code.isalpha():
            raise ValueError('invalid language code')

    if 'DOCTYPE' in xml_text or 'ENTITY' in xml_text:
        raise ValueError('DOCTYPE/ENTITY forbidden')

    try:
        root = ET.fromstring(xml_text)
    except ET.ParseError:
        raise ValueError('bad XML')

    root_tag = _local(root.tag)
    if root_tag not in ('collection', 'record'):
        raise ValueError('bad root')

    records = []
    seen_ids = set()
    record_elems = [root] if root_tag == 'record' else list(root)

    for rec in record_elems:
        if _local(rec.tag) != 'record':
            raise ValueError('unknown element')
        controls = {}
        fields = []
        rec_id = None
        for child in rec:
            ctag = _local(child.tag)
            if ctag == 'controlfield':
                tag = child.get('tag')
                if tag is None or not re.fullmatch(r'\d{3}', tag):
                    raise ValueError('bad controlfield tag')
                if tag in controls:
                    raise ValueError('duplicate controlfield tag')
                controls[tag] = _clean_text(child.text)
                if tag == '001':
                    rec_id = controls[tag]
            elif ctag == 'datafield':
                tag = child.get('tag')
                if tag is None or not re.fullmatch(r'\d{3}', tag):
                    raise ValueError('bad datafield tag')
                subfields = []
                for sf in child:
                    if _local(sf.tag) != 'subfield':
                        raise ValueError('unknown element')
                    code = sf.get('code')
                    if code is None or not re.fullmatch(r'[A-Za-z0-9]', code):
                        raise ValueError('bad subfield code')
                    subfields.append({'code': code, 'value': _clean_text(sf.text)})
                fields.append({'tag': tag, 'subfields': subfields})
            else:
                raise ValueError('unknown element')
        if rec_id is None or rec_id.strip() == '':
            raise ValueError('missing or empty 001')
        if rec_id in seen_ids:
            raise ValueError('duplicate record id')
        seen_ids.add(rec_id)
        records.append({'id': rec_id, 'controls': controls, 'fields': fields})

    records.sort(key=lambda r: r['id'])
    return {'name': contract['name'], 'result': {'records': records}}

import json
import math
from pathlib import Path


def _check_finite(obj):
    if isinstance(obj, float) and (math.isnan(obj) or math.isinf(obj)):
        raise ValueError("non-finite number")
    if isinstance(obj, dict):
        for v in obj.values():
            _check_finite(v)
    elif isinstance(obj, list):
        for v in obj:
            _check_finite(v)


def load_payload(path):
    p = Path(path)
    text = p.read_text(encoding="utf-8")
    try:
        data = json.loads(text)
    except ValueError:
        raise ValueError("invalid JSON")
    if not isinstance(data, (dict, list)):
        raise ValueError("top-level must be object or array")
    _check_finite(data)
    return data

def _clean(text):
    # collapse internal whitespace, strip leading/trailing whitespace and
    # slash/comma/colon/semicolon; periods are preserved.
    parts = text.split()
    s = " ".join(parts)
    s = s.strip()
    s = s.strip("/,:;")
    return s


def _join_subfields(field, codes):
    parts = []
    for sf in field.get("subfields", []):
        if sf.get("code") in codes:
            parts.append(sf.get("value", ""))
    return _clean(" ".join(parts))


def _parse_link(value):
    # $6 value like "880-01" or "100-01/..." -> (tag, nn)
    v = value.strip()
    if "/" in v:
        v = v.split("/", 1)[0]
    if "-" not in v:
        return None
    tag, nn = v.split("-", 1)
    if not tag or not nn:
        return None
    return tag, nn


def transform(payloads, contract):
    if len(payloads) != len(contract["inputs"]):
        raise ValueError("payload count mismatch")
    src = payloads[0]
    # When input object has exactly keys name/result, only result is business input.
    if isinstance(src, dict) and set(src.keys()) == {"name", "result"}:
        src = src["result"]

    records = src["records"]

    out_records = []
    for rec in records:
        rid = rec["id"]
        fields = rec.get("fields", [])

        authors = []
        titles = []
        # map (tag, nn) -> alternate text
        alt_map = {}

        for f in fields:
            tag = f.get("tag")
            sf6 = None
            for sf in f.get("subfields", []):
                if sf.get("code") == "6":
                    sf6 = sf.get("value", "")
                    break
            if tag == "880":
                link = _parse_link(sf6) if sf6 else None
                if link is not None:
                    ltag, nn = link
                    if ltag in ("100", "245"):
                        alt_map[(ltag, nn)] = _join_subfields(f, ("a", "b"))
            elif tag in ("100", "245"):
                link = _parse_link(sf6) if sf6 else None
                if link is not None:
                    ltag, nn = link
                    if ltag == "880":
                        alt_map[(tag, nn)] = _join_subfields(f, ("a", "b"))

        for f in fields:
            tag = f.get("tag")
            if tag == "100":
                name = _join_subfields(f, ("a", "b"))
                sf6 = None
                for sf in f.get("subfields", []):
                    if sf.get("code") == "6":
                        sf6 = sf.get("value", "")
                        break
                link = _parse_link(sf6) if sf6 else None
                alternates = []
                if link is not None and link[0] == "880":
                    alt = alt_map.get(("100", link[1]))
                    if alt is not None and alt != name:
                        alternates.append(alt)
                alternates = sorted(set(alternates))
                authors.append({"name": name, "alternates": alternates})
            elif tag == "245":
                title = _join_subfields(f, ("a", "b"))
                sf6 = None
                for sf in f.get("subfields", []):
                    if sf.get("code") == "6":
                        sf6 = sf.get("value", "")
                        break
                link = _parse_link(sf6) if sf6 else None
                alternates = []
                if link is not None and link[0] == "880":
                    alt = alt_map.get(("245", link[1]))
                    if alt is not None and alt != title:
                        alternates.append(alt)
                alternates = sorted(set(alternates))
                titles.append({"title": title, "alternates": alternates})

        out_records.append(
            {"id": rid, "authors": authors, "titles": titles}
        )

    return {"name": contract["name"], "result": {"records": out_records}}

